[tool_call Write] {"file_path":"batch_worker.ts","content":"// Batch worker for the render-job queue. Receives up to the documented
// maximum per long poll, fans the handler out per message, then deletes /
// visibility-extends in batch calls with per-entry failure handling.
// The wire contract is pinned in docs/contract.json.
import {
  ChangeMessageVisibilityBatchCommand,
  DeleteMessageBatchCommand,
  ReceiveMessageCommand,
  type Message,
} from "@aws-sdk/client-sqs";

import type { SqsSender } from "./worker.ts";

// Documented service limits (docs/contract.json).
export const MAX_BATCH_ENTRIES = 10;
export const MAX_RECEIVE_MESSAGES = 10;
export const MAX_WAIT_TIME_SECONDS = 20;

// System attributes requested on every receive (docs/contract.json).
const REQUESTED_SYSTEM_ATTRIBUTES = ["ApproximateReceiveCount", "SentTimestamp"];

export interface BatchEntry {
  Id: string;
  ReceiptHandle: string;
}

export interface BatchFailure {
  id: string;
  code: string;
  senderFault: boolean;
}

export interface ReceiveBatchOptions {
  visibilityTimeout?: number;
}

export type Outcome = "done" | "defer" | "failed";
export type BatchHandler = (message: Message) => Outcome | Promise<Outcome>;

export interface RunOnceOptions {
  deferSeconds: number;
  visibilityTimeout?: number;
}

export interface RunOnceSummary {
  received: number;
  deleted: string[];
  deferred: string[];
  failed: string[];
  deleteFailures: BatchFailure[];
}

export async function receiveBatch(
  client: SqsSender,
  queueUrl: string,
  opts?: ReceiveBatchOptions,
): Promise<Message[]> {
  const input: Record<string, unknown> = {
    QueueUrl: queueUrl,
    MaxNumberOfMessages: MAX_RECEIVE_MESSAGES,
    WaitTimeSeconds: MAX_WAIT_TIME_SECONDS,
    // AttributeNames is deprecated; MessageSystemAttributeNames replaces it.
    MessageSystemAttributeNames: [...REQUESTED_SYSTEM_ATTRIBUTES],
  };
  if (opts?.visibilityTimeout !== undefined) {
    input.VisibilityTimeout = opts.visibilityTimeout;
  }
  const out = await client.send(new ReceiveMessageCommand(input));
  // An empty long poll has no Messages field at all.
  return out.Messages ?? [];
}

export function chunkEntries<T extends { Id: string }>(entries: T[]): T[][] {
  const ids = new Set<string>();
  for (const entry of entries) {
    if (ids.has(entry.Id)) {
      throw new Error(
        `duplicate batch entry Id ${entry.Id}: the service rejects the whole request with BatchEntryIdsNotDistinct`,
      );
    }
    ids.add(entry.Id);
  }
  const chunks: T[][] = [];
  for (let i = 0; i < entries.length; i += MAX_BATCH_ENTRIES) {
    chunks.push(entries.slice(i, i + MAX_BATCH_ENTRIES));
  }
  return chunks;
}

// Shared partial-failure handling for the two batch commands: a 200 can still
// carry per-entry Failed results. Non-sender-fault entries are retried once,
// addressed by Id with the same mapped entry; sender faults and entries that
// fail again are reported.
async function sendBatches<T extends { Id: string }>(
  client: SqsSender,
  entries: T[],
  buildCommand: (chunk: T[]) => object,
): Promise<{ succeeded: string[]; failures: BatchFailure[] }> {
  const byId = new Map(entries.map((e) => [e.Id, e]));
  const succeeded: string[] = [];
  const failures: BatchFailure[] = [];
  const retryIds: string[] = [];

  for (const chunk of chunkEntries(entries)) {
    const out = await client.send(buildCommand(chunk));
    for (const ok of out.Successful ?? []) {
      succeeded.push(ok.Id);
    }
    for (const failed of out.Failed ?? []) {
      if (failed.SenderFault) {
        failures.push({ id: failed.Id, code: failed.Code, senderFault: true });
      } else {
        retryIds.push(failed.Id);
      }
    }
  }

  if (retryIds.length > 0) {
    const retryEntries = retryIds.map((id) => byId.get(id)!);
    for (const chunk of chunkEntries(retryEntries)) {
      const out = await client.send(buildCommand(chunk));
      for (const ok of out.Successful ?? []) {
        succeeded.push(ok.Id);
      }
      for (const failed of out.Failed ?? []) {
        failures.push({
          id: failed.Id,
          code: failed.Code,
          senderFault: failed.SenderFault,
        });
      }
    }
  }

  return { succeeded, failures };
}

export async function deleteMessages(
  client: SqsSender,
  queueUrl: string,
  entries: BatchEntry[],
): Promise<{ deleted: string[]; failures: BatchFailure[] }> {
  // Zero entries would fail with EmptyBatchRequest; make no call at all.
  if (entries.length === 0) {
    return { deleted: [], failures: [] };
  }
  const { succeeded, failures } = await sendBatches(
    client,
    entries,
    (chunk) => new DeleteMessageBatchCommand({ QueueUrl: queueUrl, Entries: chunk }),
  );
  return { deleted: succeeded, failures };
}

export async function extendVisibility(
  client: SqsSender,
  queueUrl: string,
  entries: BatchEntry[],
  seconds: number,
): Promise<{ extended: string[]; failures: BatchFailure[] }> {
  if (entries.length === 0) {
    return { extended: [], failures: [] };
  }
  const visibilityEntries = entries.map((e) => ({
    Id: e.Id,
    ReceiptHandle: e.ReceiptHandle,
    VisibilityTimeout: seconds,
  }));
  const { succeeded, failures } = await sendBatches(
    client,
    visibilityEntries,
    (chunk) =>
      new ChangeMessageVisibilityBatchCommand({ QueueUrl: queueUrl, Entries: chunk }),
  );
  return { extended: succeeded, failures };
}

export async function runOnce(
  client: SqsSender,
  queueUrl: string,
  handler: BatchHandler,
  options: RunOnceOptions,
): Promise<RunOnceSummary> {
  const messages = await receiveBatch(client, queueUrl, {
    visibilityTimeout: options.visibilityTimeout,
  });

  const toDelete: BatchEntry[] = [];
  const toDefer: BatchEntry[] = [];
  const failed: string[] = [];

  for (const message of messages) {
    const entry: BatchEntry = {
      Id: message.MessageId!,
      ReceiptHandle: message.ReceiptHandle!,
    };
    const outcome = await handler(message);
    if (outcome === "done") {
      toDelete.push(entry);
    } else if (outcome === "defer") {
      toDefer.push(entry);
    } else {
      // Leave the message untouched so SQS redelivers it.
      failed.push(entry.Id);
    }
  }

  const deletion = await deleteMessages(client, queueUrl, toDelete);
  await extendVisibility(client, queueUrl, toDefer, options.deferSeconds);

  return {
    received: messages.length,
    deleted: deletion.deleted,
    deferred: toDefer.map((e) => e.Id),
    failed,
    deleteFailures: deletion.failures,
  };
}
